#include <stdio.h>
#include <string.h>

void render(char *template, char *key, char *val) {
    char result[256];
    char placeholder[64];
    sprintf(placeholder, "{{%s}}", key);
    char *pos = strstr(template, placeholder);
    if (pos) {
        int prefix_len = pos - template;
        int key_len = strlen(placeholder);
        sprintf(result, "%.*s%s%s", prefix_len, template, val, pos + key_len);
        printf("%s\n", result);
    } else {
        printf("%s\n", template);
    }
}

int main() {
    render("Hello, {{name}}!", "name", "World");
    return 0;
}
